<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {api,state} from '../state';import {createLibraryApi,type ManagedUser,type LibraryRef} from '../api/libraries';import {memberUpdateBody,validateUsername,validatePassword} from '../api/accounts';import {errorMessage} from '../api/errors';import LibraryGrantEditor from '../components/LibraryGrantEditor.vue';
const client=createLibraryApi(api),admin=computed(()=>state.user?.role==='admin'),users=ref<ManagedUser[]>([]),total=ref(0),page=ref(1),q=ref(''),loading=ref(false),error=ref(''),message=ref('');
const create=ref({username:'',password:'',role:'member'}),creating=ref(false),draft=ref<{original:ManagedUser;username:string;role:string;password:string}|null>(null),busy=ref(0),detail=ref<ManagedUser|null>(null),deleting=ref(false);
const libraries=ref<LibraryRef[]>([]),grantUser=ref<ManagedUser|null>(null),grantLibraryID=ref(0),grantLibrary=ref<LibraryRef|null>(null);let epoch=0,detailEpoch=0;
async function load(){if(!admin.value)return;const g=++epoch;loading.value=true;error.value='';try{const data=await client.users(q.value,page.value,20);if(g===epoch){users.value=data.items;total.value=data.total}}catch(e){if(g===epoch)error.value=errorMessage(e)}finally{if(g===epoch)loading.value=false}}
async function add(){const issue=validateUsername(create.value.username)||validatePassword(create.value.password,true);if(issue){error.value=issue;return}creating.value=true;error.value='';try{await api.post('/users',create.value);create.value={username:'',password:'',role:'member'};message.value='用户已创建，个人书库将在首次使用时建立';page.value=1;await load()}catch(e){error.value=errorMessage(e)}finally{creating.value=false}}
function edit(user:ManagedUser){draft.value={original:user,username:user.username,role:user.role,password:''}}
async function save(){const value=draft.value;if(!value)return;const parsed=memberUpdateBody(value,value.original);if(parsed.error){error.value=parsed.error;return}busy.value=value.original.id;try{await client.updateUser(value.original.id,parsed.body);draft.value=null;message.value='用户已更新';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=0}}
async function disable(user:ManagedUser){busy.value=user.id;error.value='';try{await client.updateUser(user.id,{disabled:!user.disabled});message.value=user.disabled?'用户已恢复':'用户已停用，其登录和设备凭据已失效';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=0}}
async function inspect(user:ManagedUser){const g=++detailEpoch;error.value='';deleting.value=false;try{const value=await client.user(user.id);if(g===detailEpoch)detail.value=value}catch(e){error.value=errorMessage(e)}}
async function remove(){if(!detail.value)return;busy.value=detail.value.id;try{await api.delete('/users/'+detail.value.id);detail.value=null;message.value='用户已删除，个人库已封存';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=0}}
async function grants(user:ManagedUser){error.value='';try{libraries.value=(await client.libraries(true,true)).items.filter(lib=>!lib.archived&&lib.can_manage);grantUser.value=user;grantLibraryID.value=0}catch(e){error.value=errorMessage(e)}}
function chooseGrantLibrary(){grantLibrary.value=libraries.value.find(lib=>lib.id===grantLibraryID.value)??null}
onMounted(load);
</script>
<template><main class="page admin-users"><div class="page-title"><div><h1>用户管理</h1><p>账号维护、停用与书库授权</p></div><RouterLink class="button" to="/manage">返回管理</RouterLink></div><p v-if="!admin" role="alert">只有管理员可以管理用户。</p><template v-else><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status">{{message}}</p><section class="panel"><h2>添加用户</h2><form @submit.prevent="add"><label>用户名<input v-model="create.username" required autocomplete="off"></label><label>初始密码<input v-model="create.password" type="password" minlength="10" required autocomplete="new-password"></label><label>角色<select v-model="create.role"><option value="member">家庭成员</option><option value="admin">管理员</option></select></label><button :disabled="creating">{{creating?'创建中…':'添加用户'}}</button></form></section><form class="toolbar" @submit.prevent="page=1;load()"><input v-model="q" placeholder="搜索用户名" aria-label="搜索用户"><button>搜索</button></form><p v-if="loading" role="status">正在读取用户…</p><section v-else class="panel"><p>共 {{total}} 个用户</p><article v-for="user in users" :key="user.id" class="user-row"><template v-if="draft?.original.id===user.id"><label>用户名<input v-model="draft.username"></label><label>角色<select v-model="draft.role"><option value="member">家庭成员</option><option value="admin">管理员</option></select></label><label>新密码<input v-model="draft.password" type="password" autocomplete="new-password" placeholder="留空保留"></label><div class="row-actions"><button :disabled="!!busy" @click="save">保存修改</button><button :disabled="!!busy" @click="draft=null">取消</button></div></template><template v-else><div><strong>{{user.username}}</strong><p>{{user.role==='admin'?'管理员':'家庭成员'}} · {{user.disabled?'已停用':'正常'}}</p></div><div class="row-actions"><button @click="inspect(user)">查看</button><button @click="edit(user)">编辑</button><button :disabled="!!busy||user.id===state.user?.id" @click="disable(user)">{{user.disabled?'恢复用户':'停用用户'}}</button><button @click="grants(user)">书库授权</button><button :disabled="user.id===state.user?.id" @click="inspect(user);deleting=true">删除用户</button></div></template></article><p v-if="!users.length">没有匹配的用户。</p><div v-if="total>20" class="pagination"><button :disabled="page===1" @click="page--;load()">上一页</button><span>{{page}} / {{Math.ceil(total/20)}}</span><button :disabled="page*20>=total" @click="page++;load()">下一页</button></div></section></template></main><div v-if="detail" class="modal-backdrop" @click.self="!busy&&(detail=null)"><section class="sheet" role="dialog" aria-modal="true" aria-label="用户详情"><button class="close" :disabled="!!busy" @click="detail=null;detailEpoch++">关闭</button><h2>{{detail.username}}</h2><p>{{detail.role==='admin'?'管理员':'家庭成员'}} · {{detail.disabled?'已停用':'正常'}}</p><p>拥有 {{detail.owned_library_count??'—'}} 个书库，{{detail.active_job_count??'—'}} 个进行中的任务，{{detail.progress_count??'—'}} 条阅读记录，{{detail.note_count??'—'}} 条笔记。</p><template v-if="deleting"><p>删除后该账号无法登录，其个人库会封存，内容不会公开。其阅读记录、笔记和个人设置将删除，封存书库中的内容保留。</p><button class="primary" :disabled="!!busy||detail.id===state.user?.id" @click="remove">确认删除用户</button></template><button v-else @click="grants(detail);detail=null">管理书库授权</button></section></div><div v-if="grantUser&&!grantLibrary" class="modal-backdrop" @click.self="grantUser=null"><section class="sheet" role="dialog" aria-label="选择授权书库"><button class="close" @click="grantUser=null">关闭</button><h2>为 {{grantUser.username}} 选择书库</h2><label>书库<select v-model.number="grantLibraryID"><option value="0">请选择</option><option v-for="lib in libraries" :key="lib.id" :value="lib.id">{{lib.name}} · {{lib.content_kind==='comic'?'漫画':'图书'}}{{lib.owner_user_id===grantUser.id?'（此用户拥有）':''}}</option></select></label><button :disabled="!grantLibraryID" @click="chooseGrantLibrary">编辑授权</button></section></div><LibraryGrantEditor v-if="grantLibrary&&grantUser" :library="grantLibrary" :initial-user="grantUser" @close="grantLibrary=null;grantUser=null" @saved="message='库授权已保存'"/></template>
<style scoped>.admin-users form{max-width:650px}.user-row{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:14px 0;border-bottom:1px solid var(--border);flex-wrap:wrap}.user-row p{font-size:13px;color:var(--muted)}.user-row .row-actions{flex-wrap:wrap}.user-row label{flex:1 1 180px}@media(max-width:650px){.user-row>div:first-child{width:100%}.user-row button{font-size:13px}}
</style>
